import { reactive } from 'vue'

export const store = reactive({
    count: 0,
    increment() {
      this.count++
    },
    attributes:  [
        {key: 'MU', name: 'Mut', basevalue: 8, modValue: 8},
        {key: 'KL', name: 'Klugheit', basevalue: 8, modValue: 8},
        {key: 'IN', name: 'Intuition', basevalue: 8, modValue: 8},
        {key: 'CH', name: 'Charisma', basevalue: 8, modValue: 8},
        {key: 'FF', name: 'Fingerfertigkeit', basevalue: 8, modValue: 8},
        {key: 'GE', name: 'Gewandheit', basevalue: 8, modValue: 8},
        {key: 'ST', name: 'Stärke', basevalue: 8, modValue: 8},
        {key: 'KO', name: 'Konstitution', basevalue: 8, modValue: 8},
    ], 
    updateAttribute(attribute){
        if (attribute == null){
            window.alert("attribute is null!")
            return;
        }
        if (attribute.value > 16 || attribute < 8) {
            attribute.value = (attribute.value > 16) ? 16 : 8;
        }

        // window.alert("Attribute is: " + attribute + "with values: " + attribute.value + " and key: " + attribute.key)
        var stored = this.attributes.find(x => x.key == attribute.key);
        stored.basevalue = attribute.value;
        // window.alert("Attribute in store is: " + stored.key + " with values: " + stored.basevalue + " and key: " + stored.key)
        this.calcTalente();
    }, 
    talentgruppen:  [
        {key: 'koerper', name: 'Körper', increasedTalente: '0', talente: [
            {key: 'akrobatik', name: 'Akrobatik', calcAttributes: ['MU', 'GE', 'ST'], basevalue: 8},
            {key: 'horchen', name: 'Horchen', calcAttributes: ['KL', 'IN', 'KO'], basevalue: 8},
        ]},
    ], 
    calcTalente(){
        this.talentgruppen.talente.array.forEach(talent => {
            var sum = 0;
            talent.calcAttributes.array.forEach(tAttribute => {
                sum += this.attributes.find(x => x.key == tAttribute.key).basevalue;
            }) 
            talent.basevalue = sum / 3;
        });
    },
    //toDo: implement updateTalente
    // updateTalente(attribute){
    //     if (attribute == null){
    //         window.alert("attribute is null!")
    //         return;
    //     }
    //     // window.alert("Attribute is: " + attribute + "with values: " + attribute.value + " and key: " + attribute.key)
    //     this.attributes.find(x => x.key == attribute.key);
    // }
  })